285	            self.left = pt.x;
286	        }
287	        if pt.x > self.right {
288	            self.right = pt.x;
289	        }
290	        if pt.y < self.top {
291	            self.top = pt.y;
292	        }
293	        if pt.y > self.bottom {
294	            self.bottom = pt.y;
