313	// ---------------------------------------------------------------------------
314	// Predicates
315	// ---------------------------------------------------------------------------
316	
317	/// `CrossProduct(pt1, pt2, pt3)` — twice the signed area of the triangle,
318	/// computed in `f64` exactly as the original does.
319	#[inline]
320	pub fn cross_product(pt1: Point64, pt2: Point64, pt3: Point64) -> f64 {
321	    ((pt2.x - pt1.x) as f64) * ((pt3.y - pt2.y) as f64)
322	        - ((pt2.y - pt1.y) as f64) * ((pt3.x - pt2.x) as f64)
323	}
324	
325	/// Exact (128 bit) variant, used wherever only the *sign* matters.
326	#[inline]
327	pub fn cross_product_exact(pt1: Point64, pt2: Point64, pt3: Point64) -> i128 {
328	    let ax = pt2.x as i128 - pt1.x as i128;
329	    let ay = pt2.y as i128 - pt1.y as i128;
330	    let bx = pt3.x as i128 - pt2.x as i128;
331	    let by = pt3.y as i128 - pt2.y as i128;
332	    ax * by - ay * bx
333	}
334	
335	/// Cross product of two free vectors.
336	#[inline]
337	pub fn cross_product_d(v1: PointD, v2: PointD) -> f64 {
338	    v1.x * v2.y - v1.y * v2.x
339	}
340	
341	#[inline]
342	pub fn dot_product(pt1: Point64, pt2: Point64, pt3: Point64) -> f64 {
343	    ((pt2.x - pt1.x) as f64) * ((pt3.x - pt2.x) as f64)
344	        + ((pt2.y - pt1.y) as f64) * ((pt3.y - pt2.y) as f64)
345	}
346	
347	#[inline]
348	pub fn dot_product_d(v1: PointD, v2: PointD) -> f64 {
349	    v1.x * v2.x + v1.y * v2.y
350	}
351	
352	/// Exact cross product of the vectors `v1 = b - a` and `v2 = d - c`.
353	#[inline]
354	pub fn cross_exact(a: Point64, b: Point64, c: Point64, d: Point64) -> i128 {
355	    let v1x = b.x as i128 - a.x as i128;
356	    let v1y = b.y as i128 - a.y as i128;
357	    let v2x = d.x as i128 - c.x as i128;
358	    let v2y = d.y as i128 - c.y as i128;
359	    v1x * v2y - v1y * v2x
360	}
361	
362	/// `Area(path)` — signed area, positive for the library's "positive"
363	/// orientation.  Uses the same summation form as the original so that the
364	/// floating point result agrees bit for bit.
365	pub fn area(path: &[Point64]) -> f64 {
366	    if path.len() < 3 {
367	        return 0.0;
368	    }
369	    let mut a = 0.0f64;
370	    let mut prev = path[path.len() - 1];
371	    for &pt in path {
372	        a += ((prev.y + pt.y) as f64) * ((prev.x - pt.x) as f64);
373	        prev = pt;
374	    }
375	    a * 0.5
376	}
377	
378	pub fn areas(paths: &[Path64]) -> f64 {
379	    paths.iter().map(|p| area(p)).sum()
380	}
381	
382	/// Twice the signed area as an exact integer — safe for orientation tests.
383	pub fn area_exact_x2(path: &[Point64]) -> i128 {
384	    if path.len() < 3 {
385	        return 0;
386	    }
387	    let mut a: i128 = 0;
388	    let mut prev = path[path.len() - 1];
389	    for &pt in path {
390	        a += (prev.x as i128) * (pt.y as i128) - (pt.x as i128) * (prev.y as i128);
391	        prev = pt;
392	    }
393	    a
394	}
395	
396	/// `IsPositive(path)`.
397	#[inline]
398	pub fn is_positive(path: &[Point64]) -> bool {
399	    area(path) >= 0.0
400	}
