402	#[inline]
403	pub fn distance_sqr(a: Point64, b: Point64) -> f64 {
404	    sqr((a.x - b.x) as f64) + sqr((a.y - b.y) as f64)
405	}
406	
407	#[inline]
408	pub fn distance_sqr_d(a: PointD, b: PointD) -> f64 {
409	    sqr(a.x - b.x) + sqr(a.y - b.y)
410	}
411	
412	/// Squared perpendicular distance from `pt` to the infinite line
413	/// `line1`..`line2`.
414	pub fn perpendic_distance_from_line_sqrd(pt: PointD, line1: PointD, line2: PointD) -> f64 {
415	    let dx = line2.x - line1.x;
416	    let dy = line2.y - line1.y;
417	    if dx == 0.0 && dy == 0.0 {
418	        return distance_sqr_d(pt, line1);
419	    }
420	    let num = dy * (pt.x - line1.x) - dx * (pt.y - line1.y);
421	    (num * num) / (dx * dx + dy * dy)
422	}
423	
424	/// True when `pt` lies on the closed segment `a`..`b`.
425	pub fn point_on_segment(pt: Point64, a: Point64, b: Point64) -> bool {
426	    if cross_product_exact(a, b, pt) != 0 {
427	        return false;
428	    }
429	    pt.x >= a.x.min(b.x) && pt.x <= a.x.max(b.x) && pt.y >= a.y.min(b.y) && pt.y <= a.y.max(b.y)
430	}
