511	// ---------------------------------------------------------------------------
512	// Line helpers
513	// ---------------------------------------------------------------------------
514	
515	/// Unit normal of the edge `pt1`..`pt2`, i.e. `(dy, -dx)` normalised.
516	///
517	/// For a positively oriented (counter-clockwise) contour this points away
518	/// from the interior, which is why a positive delta inflates.
519	pub fn get_unit_normal(pt1: Point64, pt2: Point64) -> PointD {
520	    let mut dx = (pt2.x - pt1.x) as f64;
521	    let mut dy = (pt2.y - pt1.y) as f64;
522	    if dx == 0.0 && dy == 0.0 {
523	        return PointD::new(0.0, 0.0);
524	    }
525	    let inv_len = 1.0 / (dx * dx + dy * dy).sqrt();
526	    dx *= inv_len;
527	    dy *= inv_len;
528	    PointD::new(dy, -dx)
529	}
530	
531	/// `IntersectPoint` — intersection of the two *infinite* lines through
532	/// `ln1a`..`ln1b` and `ln2a`..`ln2b`.  Parallel lines return `ln1b`, which is
533	/// what the original falls back to.
534	pub fn intersect_point(ln1a: PointD, ln1b: PointD, ln2a: PointD, ln2b: PointD) -> PointD {
535	    let dx1 = ln1b.x - ln1a.x;
536	    let dy1 = ln1b.y - ln1a.y;
537	    let dx2 = ln2b.x - ln2a.x;
538	    let dy2 = ln2b.y - ln2a.y;
539	    let det = dy1 * dx2 - dy2 * dx1;
540	    if det == 0.0 {
541	        return ln1b;
542	    }
543	    let m1 = dy1 * ln1a.x - dx1 * ln1a.y;
544	    let m2 = dy2 * ln2a.x - dx2 * ln2a.y;
545	    let x = (dx2 * m1 - dx1 * m2) / det;
546	    let y = (dy2 * m1 - dy1 * m2) / det;
547	    PointD::new(x, y)
548	}
549	
550	/// Removes consecutive duplicate vertices (and, for closed paths, a trailing
551	/// vertex equal to the first).
552	pub fn strip_duplicates(path: &[Point64], is_closed_path: bool) -> Path64 {
553	    let mut out: Path64 = Vec::with_capacity(path.len());
554	    for &pt in path {
555	        if out.last().map_or(true, |&last| last != pt) {
556	            out.push(pt);
557	        }
558	    }
559	    if is_closed_path {
560	        while out.len() > 1 && out[out.len() - 1] == out[0] {
561	            out.pop();
562	        }
563	    }
564	    out
565	}
