567	pub fn reverse_path(path: &[Point64]) -> Path64 {
568	    let mut p = path.to_vec();
569	    p.reverse();
570	    p
571	}
572	
573	pub fn reverse_paths(paths: &[Path64]) -> Paths64 {
574	    paths.iter().map(|p| reverse_path(p)).collect()
575	}
