13	impl T {
14	    fn new() -> T {
15	        T { pass: 0, fail: 0 }
16	    }
17	    fn check(&mut self, name: &str, cond: bool, detail: &str) {
18	        if cond {
19	            self.pass += 1;
20	            println!("PASS  {}", name);
21	        } else {
22	            self.fail += 1;
23	            println!("FAIL  {}  <<{}>>", name, detail);
24	        }
