26	    fn eqi(&mut self, name: &str, got: i64, want: i64) {
27	        self.check(name, got == want, &format!("got {} want {}", got, want));
28	    }
29	    fn eqf(&mut self, name: &str, got: f64, want: f64, tol: f64) {
30	        self.check(
31	            name,
32	            (got - want).abs() <= tol,
33	            &format!("got {} want {} tol {}", got, want, tol),
34	        );
35	    }
36	}
